 17	import com.fasterxml.jackson.databind.ObjectMapper;
 18	import com.fasterxml.jackson.databind.SerializationFeature;
 19	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 20	import io.javalin.Javalin;
 21	import io.javalin.json.JavalinJackson;
 22	
 23	public class App {
 24	    public static void main(String[] args) {
 25	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 26	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 27	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 28	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 29	
 30	        DatabaseInitializer db = new DatabaseInitializer(dbUrl, dbUser, dbPassword);
 31	        db.initialize();
 32	
 33	        RoomRepository roomRepository = new RoomRepository(db);
 34	        ReservationRepository reservationRepository = new ReservationRepository(db);
 35	        MessageRepository messageRepository = new MessageRepository(db);
 36	
 37	        DocumentService documentService = new DocumentService();
 38	        EmailService emailService = new EmailService(messageRepository);
 39	        ReservationService reservationService = new ReservationService(
 40	            reservationRepository,
 41	            roomRepository,
 42	            documentService,
 43	            emailService
 44	        );
 45	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 46	
 47	        RoomController roomController = new RoomController(roomRepository);
 48	        ReservationController reservationController = new ReservationController(
 49	            reservationService,
 50	            reservationRepository,
 51	            roomRepository
 52	        );
 53	        MessageController messageController = new MessageController(messageRepository);
 54	        ReportController reportController = new ReportController(reportService);
 55	
 56	        ObjectMapper objectMapper = new ObjectMapper();
 57	        objectMapper.registerModule(new JavaTimeModule());
 58	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 59	
 60	        Javalin app = Javalin.create(config -> {
 61	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 62	        });
 63	
 64	        app.get("/rooms", roomController::getRooms);
 65	
 66	        app.post("/reservations", reservationController::createReservation);
 67	        app.get("/reservations/{id}", reservationController::getReservation);
 68	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 69	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 70	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 71	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 72	        app.get("/reservations/{id}/document", reservationController::getDocument);
 73	
 74	        app.get("/messages", messageController::getMessages);
 75	
 76	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 77	        app.get("/reports/revenue", reportController::getRevenueReport);
 78	
 79	        app.exception(AppException.class, (e, ctx) -> {
 80	            ctx.status(e.getStatusCode());
 81	            ctx.json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
 82	        });
 83	
 84	        app.exception(Exception.class, (e, ctx) -> {
 85	            e.printStackTrace();
 86	            ctx.status(500);
 87	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Erro interno do servidor"));
 88	        });
 89	
 90	        app.start(port);
 91	    }
 92	}
