138	public class ReportController {
139	    private final ReportService reportService;
140	
141	    public ReportController(ReportService reportService) {
142	        this.reportService = reportService;
143	    }
144	
145	    public void getOccupancyReport(Context ctx) {
146	        String dateParam = ctx.queryParam("date");
147	        if (dateParam == null) {
148	            throw AppException.invalidRequest("Parâmetro 'date' é obrigatório");
149	        }
150	
151	        LocalDate date;
152	        try {
153	            date = LocalDate.parse(dateParam);
154	        } catch (DateTimeParseException e) {
155	            throw AppException.invalidRequest("Formato de data inválido: " + dateParam);
156	        }
157	
158	        String csv = reportService.generateOccupancyReport(date);
159	        ctx.contentType("text/csv; charset=utf-8");
160	        ctx.result(csv);
161	    }
162	
163	    public void getRevenueReport(Context ctx) {
164	        String monthParam = ctx.queryParam("month");
165	        if (monthParam == null) {
166	            throw AppException.invalidRequest("Parâmetro 'month' é obrigatório");
167	        }
168	
169	        YearMonth month;
170	        try {
171	            month = YearMonth.parse(monthParam);
172	        } catch (DateTimeParseException e) {
173	            throw AppException.invalidRequest("Formato de mês inválido: " + monthParam);
174	        }
175	
176	        String csv = reportService.generateRevenueReport(month);
177	        ctx.contentType("text/csv; charset=utf-8");
178	        ctx.result(csv);
179	    }
180	}
181	package br.com.pousada.marealta.controller;
182	
183	import br.com.pousada.marealta.exception.AppException;
184	import br.com.pousada.marealta.model.*;
185	import br.com.pousada.marealta.repository.ReservationRepository;
186	import br.com.pousada.marealta.repository.RoomRepository;
187	import br.com.pousada.marealta.service.ReservationService;
188	import io.javalin.http.Context;
189	
190	import java.time.LocalDate;
191	import java.time.format.DateTimeParseException;
192	import java.util.HashMap;
193	import java.util.Map;
194	
195	public class ReservationController {
196	    private final ReservationService reservationService;
197	    private final ReservationRepository reservationRepository;
198	    private final RoomRepository roomRepository;
199	
200	    public ReservationController(ReservationService reservationService,
201	                                ReservationRepository reservationRepository,
202	                                RoomRepository roomRepository) {
203	        this.reservationService = reservationService;
204	        this.reservationRepository = reservationRepository;
205	        this.roomRepository = roomRepository;
206	    }
207	
208	    public void createReservation(Context ctx) {
209	        Map<String, Object> body = ctx.bodyAsClass(Map.class);
210	
211	        validateRequiredFields(body, "roomNumber", "guestName", "guestEmail", "checkIn", "checkOut", "guests", "ratePlan");
212	
213	        String roomNumber = (String) body.get("roomNumber");
214	        String guestName = (String) body.get("guestName");
215	        String guestEmail = (String) body.get("guestEmail");
216	        LocalDate checkIn = parseDate((String) body.get("checkIn"));
217	        LocalDate checkOut = parseDate((String) body.get("checkOut"));
218	        int guests = getIntValue(body, "guests");
219	        RatePlan ratePlan = parseRatePlan((String) body.get("ratePlan"));
220	
221	        if (!checkIn.isBefore(checkOut)) {
222	            throw AppException.invalidRequest("Data de saída deve ser posterior à data de entrada");
223	        }
224	
225	        GuestIdentification identification = parseIdentification(body);
226	
227	        Reservation reservation = new Reservation();
228	        reservation.setRoomNumber(roomNumber);
229	        reservation.setGuestName(guestName);
230	        reservation.setGuestEmail(guestEmail);
231	        reservation.setIdentification(identification);
232	        reservation.setCheckIn(checkIn);
233	        reservation.setCheckOut(checkOut);
234	        reservation.setGuests(guests);
235	        reservation.setRatePlan(ratePlan);
236	
237	        Reservation created = reservationService.createReservation(reservation);
238	        ctx.status(201).json(toReservationDto(created));
239	    }
240	
241	    public void getReservation(Context ctx) {
242	        Long id = ctx.pathParamAsClass("id", Long.class).get();
243	        Reservation reservation = reservationRepository.findById(id)
244	            .orElseThrow(AppException::reservationNotFound);
245	        ctx.json(toReservationDto(reservation));
246	    }
247	
248	    public void confirmReservation(Context ctx) {
249	        Long id = ctx.pathParamAsClass("id", Long.class).get();
250	        Reservation reservation = reservationService.confirmReservation(id);
251	        ctx.json(toReservationDto(reservation));
252	    }
253	
254	    public void cancelReservation(Context ctx) {
255	        Long id = ctx.pathParamAsClass("id", Long.class).get();
256	        Reservation reservation = reservationService.cancelReservation(id);
257	        ctx.json(toReservationDto(reservation));
258	    }
259	
260	    public void checkIn(Context ctx) {
261	        Long id = ctx.pathParamAsClass("id", Long.class).get();
262	        Reservation reservation = reservationService.checkIn(id);
263	        ctx.json(toReservationDto(reservation));
264	    }
265	
266	    public void checkOut(Context ctx) {
267	        Long id = ctx.pathParamAsClass("id", Long.class).get();
268	        Reservation reservation = reservationService.checkOut(id);
269	        Document document = reservationService.getDocument(id);
270	        ctx.json(toDocumentDto(document));
271	    }
272	
273	    public void getDocument(Context ctx) {
274	        Long id = ctx.pathParamAsClass("id", Long.class).get();
275	        Document document = reservationService.getDocument(id);
276	        ctx.json(toDocumentDto(document));
277	    }
278	
279	    private void validateRequiredFields(Map<String, Object> body, String... fields) {
280	        for (String field : fields) {
281	            if (!body.containsKey(field) || body.get(field) == null) {
282	                throw AppException.invalidRequest("Campo obrigatório ausente: " + field);
283	            }
284	        }
285	    }
286	
287	    private LocalDate parseDate(String dateStr) {
288	        try {
289	            return LocalDate.parse(dateStr);
290	        } catch (DateTimeParseException e) {
291	            throw AppException.invalidRequest("Formato de data inválido: " + dateStr);
292	        }
293	    }
294	
295	    private int getIntValue(Map<String, Object> body, String field) {
296	        Object value = body.get(field);
297	        if (value instanceof Integer) {
298	            return (Integer) value;
299	        } else if (value instanceof Number) {
300	            return ((Number) value).intValue();
301	        }
302	        throw AppException.invalidRequest("Valor inválido para " + field);
303	    }
304	
305	    private RatePlan parseRatePlan(String ratePlanStr) {
306	        try {
307	            return RatePlan.valueOf(ratePlanStr);
308	        } catch (IllegalArgumentException e) {
309	            throw AppException.invalidRequest("Plano de tarifa inválido: " + ratePlanStr);
310	        }
311	    }
312	
313	    private GuestIdentification parseIdentification(Map<String, Object> body) {
314	        String cpf = (String) body.get("guestCpf");
315	        String cnpj = (String) body.get("companyCnpj");
316	        String companyName = (String) body.get("companyName");
317	        String passport = (String) body.get("guestPassport");
318	        String country = (String) body.get("guestCountry");
319	
320	        int typeCount = 0;
321	        if (cpf != null) typeCount++;
322	        if (cnpj != null) typeCount++;
323	        if (passport != null) typeCount++;
324	
325	        if (typeCount != 1) {
326	            throw AppException.invalidRequest("Deve haver exatamente um tipo de identificação");
327	        }
328	
329	        if (cpf != null) {
330	            return new GuestIdentification.Individual(cpf);
331	        } else if (cnpj != null) {
332	            if (companyName == null) {
333	                throw AppException.invalidRequest("companyName é obrigatório quando companyCnpj é informado");
334	            }
335	            return new GuestIdentification.Company(cnpj, companyName);
336	        } else {
337	            if (country == null) {
338	                throw AppException.invalidRequest("guestCountry é obrigatório quando guestPassport é informado");
339	            }
340	            return new GuestIdentification.Foreign(passport, country);
341	        }
342	    }
343	
344	    private Map<String, Object> toReservationDto(Reservation reservation) {
345	        Map<String, Object> dto = new HashMap<>();
346	        dto.put("id", reservation.getId());
347	        dto.put("roomNumber", reservation.getRoomNumber());
348	        dto.put("guestName", reservation.getGuestName());
349	        dto.put("guestEmail", reservation.getGuestEmail());
350	
351	        GuestIdentification identification = reservation.getIdentification();
352	        if (identification instanceof GuestIdentification.Individual individual) {
353	            dto.put("guestCpf", individual.cpf());
354	            dto.put("companyCnpj", null);
355	            dto.put("companyName", null);
356	            dto.put("guestPassport", null);
357	            dto.put("guestCountry", null);
358	        } else if (identification instanceof GuestIdentification.Company company) {
359	            dto.put("guestCpf", null);
360	            dto.put("companyCnpj", company.cnpj());
361	            dto.put("companyName", company.companyName());
362	            dto.put("guestPassport", null);
363	            dto.put("guestCountry", null);
364	        } else if (identification instanceof GuestIdentification.Foreign foreign) {
365	            dto.put("guestCpf", null);
366	            dto.put("companyCnpj", null);
367	            dto.put("companyName", null);
368	            dto.put("guestPassport", foreign.passport());
369	            dto.put("guestCountry", foreign.country());
370	        }
371	
372	        dto.put("checkIn", reservation.getCheckIn().toString());
373	        dto.put("checkOut", reservation.getCheckOut().toString());
374	        dto.put("guests", reservation.getGuests());
375	        dto.put("ratePlan", reservation.getRatePlan().name());
376	        dto.put("nights", reservation.getNights());
377	        dto.put("subtotal", reservation.getSubtotal());
378	        dto.put("discount", reservation.getDiscount());
379	        dto.put("total", reservation.getTotal());
380	        dto.put("status", reservation.getStatus().name());
381	        dto.put("amountPaid", reservation.getAmountPaid());
382	        dto.put("refund", reservation.getRefund());
383	
384	        return dto;
385	    }
386	
387	    private Map<String, Object> toDocumentDto(Document document) {
388	        Map<String, Object> dto = new HashMap<>();
389	        dto.put("title", document.getTitle());
390	        dto.put("reservationId", document.getReservationId());
391	        dto.put("guestName", document.getGuestName());
392	        dto.put("guestCpf", document.getGuestCpf());
393	        dto.put("companyCnpj", document.getCompanyCnpj());
394	        dto.put("companyName", document.getCompanyName());
395	        dto.put("guestPassport", document.getGuestPassport());
396	        dto.put("guestCountry", document.getGuestCountry());
397	        dto.put("roomNumber", document.getRoomNumber());
398	        dto.put("roomType", document.getRoomType().name());
399	        dto.put("checkIn", document.getCheckIn().toString());
400	        dto.put("checkOut", document.getCheckOut().toString());
401	        dto.put("nights", document.getNights());
402	        dto.put("subtotal", document.getSubtotal());
403	        dto.put("discount", document.getDiscount());
404	        dto.put("total", document.getTotal());
405	        dto.put("text", document.getText());
406	        return dto;
407	    }
408	}
