275	        Document document = reservationService.getDocument(id);
276	        ctx.json(toDocumentDto(document));
277	    }
278	
279	    private void validateRequiredFields(Map<String, Object> body, String... fields) {
280	        for (String field : fields) {
281	            if (!body.containsKey(field) || body.get(field) == null) {
282	                throw AppException.invalidRequest("Campo obrigatório ausente: " + field);
283	            }
284	        }
285	    }
286	
287	    private LocalDate parseDate(String dateStr) {
288	        try {
289	            return LocalDate.parse(dateStr);
290	        } catch (DateTimeParseException e) {
291	            throw AppException.invalidRequest("Formato de data inválido: " + dateStr);
292	        }
293	    }
294	
295	    private int getIntValue(Map<String, Object> body, String field) {
296	        Object value = body.get(field);
297	        if (value instanceof Integer) {
298	            return (Integer) value;
299	        } else if (value instanceof Number) {
300	            return ((Number) value).intValue();
301	        }
302	        throw AppException.invalidRequest("Valor inválido para " + field);
303	    }
304	
305	    private RatePlan parseRatePlan(String ratePlanStr) {
306	        try {
307	            return RatePlan.valueOf(ratePlanStr);
308	        } catch (IllegalArgumentException e) {
309	            throw AppException.invalidRequest("Plano de tarifa inválido: " + ratePlanStr);
310	        }
311	    }
312	
313	    private GuestIdentification parseIdentification(Map<String, Object> body) {
314	        String cpf = (String) body.get("guestCpf");
315	        String cnpj = (String) body.get("companyCnpj");
316	        String companyName = (String) body.get("companyName");
317	        String passport = (String) body.get("guestPassport");
318	        String country = (String) body.get("guestCountry");
319	
320	        int typeCount = 0;
321	        if (cpf != null) typeCount++;
322	        if (cnpj != null) typeCount++;
323	        if (passport != null) typeCount++;
324	
325	        if (typeCount != 1) {
326	            throw AppException.invalidRequest("Deve haver exatamente um tipo de identificação");
327	        }
328	
329	        if (cpf != null) {
330	            return new GuestIdentification.Individual(cpf);
331	        } else if (cnpj != null) {
332	            if (companyName == null) {
333	                throw AppException.invalidRequest("companyName é obrigatório quando companyCnpj é informado");
334	            }
335	            return new GuestIdentification.Company(cnpj, companyName);
336	        } else {
337	            if (country == null) {
338	                throw AppException.invalidRequest("guestCountry é obrigatório quando guestPassport é informado");
339	            }
340	            return new GuestIdentification.Foreign(passport, country);
341	        }
342	    }
343	
344	    private Map<String, Object> toReservationDto(Reservation reservation) {
345	        Map<String, Object> dto = new HashMap<>();
346	        dto.put("id", reservation.getId());
347	        dto.put("roomNumber", reservation.getRoomNumber());
348	        dto.put("guestName", reservation.getGuestName());
349	        dto.put("guestEmail", reservation.getGuestEmail());
350	
351	        GuestIdentification identification = reservation.getIdentification();
352	        if (identification instanceof GuestIdentification.Individual individual) {
353	            dto.put("guestCpf", individual.cpf());
354	            dto.put("companyCnpj", null);
355	            dto.put("companyName", null);
356	            dto.put("guestPassport", null);
357	            dto.put("guestCountry", null);
358	        } else if (identification instanceof GuestIdentification.Company company) {
359	            dto.put("guestCpf", null);
360	            dto.put("companyCnpj", company.cnpj());
361	            dto.put("companyName", company.companyName());
362	            dto.put("guestPassport", null);
363	            dto.put("guestCountry", null);
364	        } else if (identification instanceof GuestIdentification.Foreign foreign) {
365	            dto.put("guestCpf", null);
366	            dto.put("companyCnpj", null);
367	            dto.put("companyName", null);
368	            dto.put("guestPassport", foreign.passport());
369	            dto.put("guestCountry", foreign.country());
370	        }
371	
372	        dto.put("checkIn", reservation.getCheckIn().toString());
373	        dto.put("checkOut", reservation.getCheckOut().toString());
374	        dto.put("guests", reservation.getGuests());
375	        dto.put("ratePlan", reservation.getRatePlan().name());
376	        dto.put("nights", reservation.getNights());
377	        dto.put("subtotal", reservation.getSubtotal());
378	        dto.put("discount", reservation.getDiscount());
379	        dto.put("total", reservation.getTotal());
380	        dto.put("status", reservation.getStatus().name());
381	        dto.put("amountPaid", reservation.getAmountPaid());
382	        dto.put("refund", reservation.getRefund());
383	
384	        return dto;
385	    }
386	
387	    private Map<String, Object> toDocumentDto(Document document) {
388	        Map<String, Object> dto = new HashMap<>();
389	        dto.put("title", document.getTitle());
390	        dto.put("reservationId", document.getReservationId());
391	        dto.put("guestName", document.getGuestName());
392	        dto.put("guestCpf", document.getGuestCpf());
393	        dto.put("companyCnpj", document.getCompanyCnpj());
394	        dto.put("companyName", document.getCompanyName());
395	        dto.put("guestPassport", document.getGuestPassport());
396	        dto.put("guestCountry", document.getGuestCountry());
397	        dto.put("roomNumber", document.getRoomNumber());
398	        dto.put("roomType", document.getRoomType().name());
399	        dto.put("checkIn", document.getCheckIn().toString());
400	        dto.put("checkOut", document.getCheckOut().toString());
401	        dto.put("nights", document.getNights());
402	        dto.put("subtotal", document.getSubtotal());
403	        dto.put("discount", document.getDiscount());
404	        dto.put("total", document.getTotal());
405	        dto.put("text", document.getText());
406	        return dto;
407	    }
408	}
