  2	
  3	import br.com.pousada.marealta.model.Message;
  4	import br.com.pousada.marealta.util.DatabaseInitializer;
  5	
  6	import java.sql.*;
  7	import java.util.ArrayList;
  8	import java.util.List;
  9	
 10	public class MessageRepository {
 11	    private final DatabaseInitializer db;
 12	
 13	    public MessageRepository(DatabaseInitializer db) {
 14	        this.db = db;
 15	    }
 16	
 17	    public Message create(Message message) {
 18	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
 19	
 20	        try (Connection conn = db.getConnection();
 21	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 22	
 23	            stmt.setString(1, message.getChannel());
 24	            stmt.setString(2, message.getTo());
 25	            stmt.setString(3, message.getSubject());
 26	            stmt.setString(4, message.getBody());
 27	
 28	            stmt.executeUpdate();
 29	
 30	            ResultSet rs = stmt.getGeneratedKeys();
 31	            if (rs.next()) {
 32	                message.setId(rs.getLong(1));
 33	            }
 34	
 35	            return message;
 36	        } catch (SQLException e) {
 37	            throw new RuntimeException("Erro ao criar mensagem", e);
 38	        }
 39	    }
 40	
 41	    public List<Message> findAll() {
 42	        String sql = "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id";
 43	
 44	        try (Connection conn = db.getConnection();
 45	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 46	
 47	            ResultSet rs = stmt.executeQuery();
 48	            List<Message> messages = new ArrayList<>();
 49	
 50	            while (rs.next()) {
 51	                Message message = new Message();
 52	                message.setId(rs.getLong("id"));
 53	                message.setChannel(rs.getString("channel"));
 54	                message.setTo(rs.getString("recipient"));
 55	                message.setSubject(rs.getString("subject"));
 56	                message.setBody(rs.getString("body"));
 57	                messages.add(message);
 58	            }
 59	
 60	            return messages;
 61	        } catch (SQLException e) {
 62	            throw new RuntimeException("Erro ao buscar mensagens", e);
 63	        }
 64	    }
 65	}
 66	package br.com.pousada.marealta.repository;
 67	
 68	import br.com.pousada.marealta.model.GuestIdentification;
 69	import br.com.pousada.marealta.model.RatePlan;
 70	import br.com.pousada.marealta.model.Reservation;
