 72	import br.com.pousada.marealta.util.DatabaseInitializer;
 73	
 74	import java.sql.*;
 75	import java.time.LocalDate;
 76	import java.time.YearMonth;
 77	import java.util.ArrayList;
 78	import java.util.List;
 79	import java.util.Optional;
 80	
 81	public class ReservationRepository {
 82	    private final DatabaseInitializer db;
 83	
 84	    public ReservationRepository(DatabaseInitializer db) {
 85	        this.db = db;
 86	    }
 87	
 88	    public Reservation create(Reservation reservation) {
 89	        String sql = """
 90	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj,
 91	                company_name, guest_passport, guest_country, check_in, check_out, guests, rate_plan,
 92	                nights, subtotal, discount, total, status, amount_paid, refund)
 93	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 94	            """;
 95	
 96	        try (Connection conn = db.getConnection();
 97	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 98	
 99	            stmt.setString(1, reservation.getRoomNumber());
100	            stmt.setString(2, reservation.getGuestName());
101	            stmt.setString(3, reservation.getGuestEmail());
102	
103	            setIdentificationFields(stmt, reservation.getIdentification());
104	
105	            stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
106	            stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
107	            stmt.setInt(11, reservation.getGuests());
108	            stmt.setString(12, reservation.getRatePlan().name());
109	            stmt.setInt(13, reservation.getNights());
110	            stmt.setBigDecimal(14, reservation.getSubtotal());
111	            stmt.setBigDecimal(15, reservation.getDiscount());
112	            stmt.setBigDecimal(16, reservation.getTotal());
113	            stmt.setString(17, reservation.getStatus().name());
114	            stmt.setBigDecimal(18, reservation.getAmountPaid());
115	
116	            if (reservation.getRefund() != null) {
117	                stmt.setBigDecimal(19, reservation.getRefund());
118	            } else {
119	                stmt.setNull(19, Types.DECIMAL);
120	            }
121	
122	            stmt.executeUpdate();
123	
124	            ResultSet rs = stmt.getGeneratedKeys();
125	            if (rs.next()) {
126	                reservation.setId(rs.getLong(1));
127	            }
128	
129	            return reservation;
130	        } catch (SQLException e) {
131	            throw new RuntimeException("Erro ao criar reserva", e);
132	        }
133	    }
134	
135	    public Optional<Reservation> findById(Long id) {
136	        String sql = """
137	            SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
138	                guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
139	                subtotal, discount, total, status, amount_paid, refund
140	            FROM reservations WHERE id = ?
141	            """;
142	
143	        try (Connection conn = db.getConnection();
144	             PreparedStatement stmt = conn.prepareStatement(sql)) {
145	
146	            stmt.setLong(1, id);
147	            ResultSet rs = stmt.executeQuery();
148	
149	            if (rs.next()) {
150	                return Optional.of(mapReservation(rs));
151	            }
152	            return Optional.empty();
153	        } catch (SQLException e) {
154	            throw new RuntimeException("Erro ao buscar reserva", e);
155	        }
156	    }
157	
158	    public void update(Reservation reservation) {
159	        String sql = """
160	            UPDATE reservations SET room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
161	                company_cnpj = ?, company_name = ?, guest_passport = ?, guest_country = ?,
162	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?, nights = ?, subtotal = ?,
163	                discount = ?, total = ?, status = ?, amount_paid = ?, refund = ?
164	            WHERE id = ?
165	            """;
166	
167	        try (Connection conn = db.getConnection();
168	             PreparedStatement stmt = conn.prepareStatement(sql)) {
169	
170	            stmt.setString(1, reservation.getRoomNumber());
171	            stmt.setString(2, reservation.getGuestName());
172	            stmt.setString(3, reservation.getGuestEmail());
173	
174	            setIdentificationFields(stmt, reservation.getIdentification());
175	
176	            stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
177	            stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
178	            stmt.setInt(11, reservation.getGuests());
179	            stmt.setString(12, reservation.getRatePlan().name());
180	            stmt.setInt(13, reservation.getNights());
181	            stmt.setBigDecimal(14, reservation.getSubtotal());
182	            stmt.setBigDecimal(15, reservation.getDiscount());
183	            stmt.setBigDecimal(16, reservation.getTotal());
184	            stmt.setString(17, reservation.getStatus().name());
185	            stmt.setBigDecimal(18, reservation.getAmountPaid());
186	
187	            if (reservation.getRefund() != null) {
188	                stmt.setBigDecimal(19, reservation.getRefund());
189	            } else {
190	                stmt.setNull(19, Types.DECIMAL);
191	            }
192	
193	            stmt.setLong(20, reservation.getId());
194	
195	            stmt.executeUpdate();
196	        } catch (SQLException e) {
197	            throw new RuntimeException("Erro ao atualizar reserva", e);
198	        }
199	    }
200	
201	    public boolean hasConflictingReservation(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
202	        String sql = """
203	            SELECT COUNT(*) FROM reservations
204	            WHERE room_number = ? AND status != 'CANCELLED'
205	                AND check_in < ? AND check_out > ?
206	            """ + (excludeId != null ? " AND id != ?" : "");
207	
208	        try (Connection conn = db.getConnection();
209	             PreparedStatement stmt = conn.prepareStatement(sql)) {
210	
211	            stmt.setString(1, roomNumber);
212	            stmt.setDate(2, Date.valueOf(checkOut));
213	            stmt.setDate(3, Date.valueOf(checkIn));
214	
215	            if (excludeId != null) {
216	                stmt.setLong(4, excludeId);
217	            }
218	
219	            ResultSet rs = stmt.executeQuery();
220	            rs.next();
221	            return rs.getInt(1) > 0;
222	        } catch (SQLException e) {
223	            throw new RuntimeException("Erro ao verificar conflito de reservas", e);
224	        }
225	    }
