227	    public List<Reservation> findByCheckInMonth(YearMonth month) {
228	        String sql = """
229	            SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
230	                guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
231	                subtotal, discount, total, status, amount_paid, refund
232	            FROM reservations
233	            WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
234	            ORDER BY check_in, id
235	            """;
236	
237	        try (Connection conn = db.getConnection();
238	             PreparedStatement stmt = conn.prepareStatement(sql)) {
239	
