271	public class ReservationService {
272	    private final ReservationRepository reservationRepository;
273	    private final RoomRepository roomRepository;
274	    private final DocumentService documentService;
275	    private final EmailService emailService;
276	
277	    public ReservationService(ReservationRepository reservationRepository,
278	                            RoomRepository roomRepository,
279	                            DocumentService documentService,
280	                            EmailService emailService) {
281	        this.reservationRepository = reservationRepository;
282	        this.roomRepository = roomRepository;
283	        this.documentService = documentService;
284	        this.emailService = emailService;
285	    }
286	
287	    public Reservation createReservation(Reservation reservation) {
288	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
289	            .orElseThrow(AppException::roomNotFound);
290	
291	        if (reservation.getGuests() < 1) {
292	            throw AppException.invalidRequest("Número de hóspedes deve ser no mínimo 1");
293	        }
294	
295	        if (reservation.getGuests() > room.getCapacity()) {
296	            throw AppException.capacityExceeded();
297	        }
298	
299	        if (reservationRepository.hasConflictingReservation(
300	                reservation.getRoomNumber(),
301	                reservation.getCheckIn(),
302	                reservation.getCheckOut(),
303	                null)) {
304	            throw AppException.roomUnavailable();
305	        }
306	
307	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
308	        reservation.setNights(nights);
309	
310	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(
311	            room.getType(),
312	            reservation.getCheckIn(),
313	            reservation.getCheckOut()
314	        );
315	        reservation.setSubtotal(subtotal);
316	
317	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, reservation.getRatePlan());
318	        reservation.setDiscount(discount);
319	
320	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
321	        reservation.setTotal(total);
322	
323	        reservation.setStatus(ReservationStatus.PENDING);
324	        reservation.setAmountPaid(BigDecimal.ZERO);
325	        reservation.setRefund(null);
326	
327	        return reservationRepository.create(reservation);
328	    }
329	
330	    public Reservation confirmReservation(Long id) {
331	        Reservation reservation = reservationRepository.findById(id)
332	            .orElseThrow(AppException::reservationNotFound);
333	
334	        if (reservation.getStatus() != ReservationStatus.PENDING) {
335	            throw AppException.operationNotAllowed();
336	        }
337	
338	        reservation.setStatus(ReservationStatus.CONFIRMED);
339	        reservation.setAmountPaid(reservation.getTotal());
340	        reservationRepository.update(reservation);
341	
342	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
343	            .orElseThrow(AppException::roomNotFound);
344	
345	        Document document = documentService.generateDocument(reservation, room);
346	        emailService.sendConfirmationEmail(
347	            reservation.getGuestEmail(),
348	            reservation.getGuestName(),
349	            document
350	        );
351	
352	        return reservation;
353	    }
354	
355	    public Reservation cancelReservation(Long id) {
356	        Reservation reservation = reservationRepository.findById(id)
357	            .orElseThrow(AppException::reservationNotFound);
358	
359	        if (reservation.getStatus() != ReservationStatus.PENDING &&
360	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
361	            throw AppException.operationNotAllowed();
362	        }
363	
364	        reservation.setStatus(ReservationStatus.CANCELLED);
365	
366	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
367	            reservation.setRefund(reservation.getAmountPaid());
368	        } else {
369	            reservation.setRefund(BigDecimal.ZERO);
370	        }
371	
372	        reservationRepository.update(reservation);
373	        return reservation;
374	    }
375	
376	    public Reservation checkIn(Long id) {
377	        Reservation reservation = reservationRepository.findById(id)
378	            .orElseThrow(AppException::reservationNotFound);
379	
380	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
381	            throw AppException.operationNotAllowed();
382	        }
383	
384	        reservation.setStatus(ReservationStatus.CHECKED_IN);
385	        reservationRepository.update(reservation);
386	        return reservation;
387	    }
388	
389	    public Reservation checkOut(Long id) {
390	        Reservation reservation = reservationRepository.findById(id)
391	            .orElseThrow(AppException::reservationNotFound);
392	
393	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
394	            throw AppException.operationNotAllowed();
395	        }
396	
397	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
398	        reservationRepository.update(reservation);
399	        return reservation;
400	    }
401	
402	    public Document getDocument(Long id) {
403	        Reservation reservation = reservationRepository.findById(id)
404	            .orElseThrow(AppException::reservationNotFound);
405	
406	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
407	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
408	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
409	            throw AppException.operationNotAllowed();
410	        }
411	
412	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
413	            .orElseThrow(AppException::roomNotFound);
414	
415	        return documentService.generateDocument(reservation, room);
416	    }
417	}
