502	package br.com.pousada.marealta.util;
503	
504	import br.com.pousada.marealta.model.RatePlan;
505	import br.com.pousada.marealta.model.RoomType;
506	
507	import java.math.BigDecimal;
508	import java.math.RoundingMode;
509	import java.time.LocalDate;
510	import java.time.Month;
511	
512	public class PriceCalculator {
513	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
514	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
515	
516	    public static boolean isHighSeason(LocalDate date) {
517	        Month month = date.getMonth();
518	        int day = date.getDayOfMonth();
519	
520	        if (month == Month.JULY) {
521	            return true;
522	        }
523	
524	        if (month == Month.DECEMBER && day >= 15) {
525	            return true;
526	        }
527	
528	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
529	            return true;
530	        }
531	
532	        return false;
533	    }
534	
535	    public static BigDecimal calculateNightPrice(RoomType roomType, LocalDate date) {
536	        BigDecimal basePrice = roomType.getNightlyRate();
537	        if (isHighSeason(date)) {
538	            return basePrice.multiply(HIGH_SEASON_MULTIPLIER)
539	                    .setScale(2, RoundingMode.HALF_EVEN);
540	        }
541	        return basePrice;
542	    }
543	
544	    public static BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
545	        BigDecimal subtotal = BigDecimal.ZERO;
546	        LocalDate currentDate = checkIn;
547	
548	        while (currentDate.isBefore(checkOut)) {
549	            BigDecimal nightPrice = calculateNightPrice(roomType, currentDate);
550	            subtotal = subtotal.add(nightPrice);
551	            currentDate = currentDate.plusDays(1);
552	        }
553	
554	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
555	    }
556	
557	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
558	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
559	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
560	                    .setScale(2, RoundingMode.HALF_EVEN);
561	        }
562	        return BigDecimal.ZERO;
563	    }
564	
565	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
566	        return subtotal.subtract(discount)
567	                .setScale(2, RoundingMode.HALF_EVEN);
568	    }
569	}
