 15	    private static final DateTimeFormatter EN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 16	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
 17	
 18	    public Document generateDocument(Reservation reservation, Room room) {
 19	        Document document = new Document();
 20	        document.setReservationId(reservation.getId());
 21	        document.setGuestName(reservation.getGuestName());
 22	        document.setRoomNumber(reservation.getRoomNumber());
 23	        document.setRoomType(room.getType());
 24	        document.setCheckIn(reservation.getCheckIn());
 25	        document.setCheckOut(reservation.getCheckOut());
 26	        document.setNights(reservation.getNights());
 27	        document.setSubtotal(reservation.getSubtotal());
 28	        document.setDiscount(reservation.getDiscount());
 29	        document.setTotal(reservation.getTotal());
 30	
 31	        GuestIdentification identification = reservation.getIdentification();
 32	
 33	        if (identification instanceof GuestIdentification.Individual individual) {
 34	            document.setTitle("Comprovante de reserva");
 35	            document.setGuestCpf(individual.cpf());
 36	            document.setText(generateReceiptText(document));
 37	        } else if (identification instanceof GuestIdentification.Company company) {
 38	            document.setTitle("Fatura de hospedagem");
 39	            document.setCompanyCnpj(company.cnpj());
 40	            document.setCompanyName(company.companyName());
 41	            document.setText(generateInvoiceText(document));
 42	        } else if (identification instanceof GuestIdentification.Foreign foreign) {
 43	            document.setTitle("Booking receipt");
 44	            document.setGuestPassport(foreign.passport());
 45	            document.setGuestCountry(foreign.country());
 46	            document.setText(generateBookingReceiptText(document));
 47	        }
 48	
 49	        return document;
 50	    }
 51	
 52	    private String generateReceiptText(Document doc) {
 53	        StringBuilder sb = new StringBuilder();
 54	        sb.append("Comprovante de reserva nº ").append(doc.getReservationId()).append("\n");
 55	        sb.append("Hóspede: ").append(doc.getGuestName())
 56	          .append(" (CPF ").append(formatCpf(doc.getGuestCpf())).append(")\n");
 57	        sb.append("Quarto: ").append(doc.getRoomNumber())
 58	          .append(" (").append(doc.getRoomType()).append(")\n");
 59	        sb.append("Entrada: ").append(doc.getCheckIn().format(PT_DATE_FORMAT))
 60	          .append(" | Saída: ").append(doc.getCheckOut().format(PT_DATE_FORMAT))
 61	          .append(" | ").append(doc.getNights())
 62	          .append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
 63	        sb.append("Diárias: ").append(BRL_FORMAT.format(doc.getSubtotal())).append("\n");
 64	
 65	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 66	            sb.append("Desconto: ").append(BRL_FORMAT.format(doc.getDiscount())).append("\n");
 67	        }
 68	
 69	        sb.append("Total: ").append(BRL_FORMAT.format(doc.getTotal()));
 70	
 71	        return sb.toString();
 72	    }
 73	
 74	    private String generateInvoiceText(Document doc) {
 75	        StringBuilder sb = new StringBuilder();
 76	        sb.append("Fatura de hospedagem nº ").append(doc.getReservationId()).append("\n");
 77	        sb.append("Empresa: ").append(doc.getCompanyName())
 78	          .append(" (CNPJ ").append(formatCnpj(doc.getCompanyCnpj())).append(")\n");
 79	        sb.append("Hóspede: ").append(doc.getGuestName()).append("\n");
 80	        sb.append("Quarto: ").append(doc.getRoomNumber())
 81	          .append(" (").append(doc.getRoomType()).append(")\n");
 82	        sb.append("Entrada: ").append(doc.getCheckIn().format(PT_DATE_FORMAT))
 83	          .append(" | Saída: ").append(doc.getCheckOut().format(PT_DATE_FORMAT))
 84	          .append(" | ").append(doc.getNights())
 85	          .append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
 86	        sb.append("Diárias: ").append(BRL_FORMAT.format(doc.getSubtotal())).append("\n");
 87	
 88	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 89	            sb.append("Desconto: ").append(BRL_FORMAT.format(doc.getDiscount())).append("\n");
 90	        }
 91	
 92	        sb.append("Total: ").append(BRL_FORMAT.format(doc.getTotal())).append("\n");
 93	
 94	        BigDecimal iss = doc.getTotal().multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
 95	        sb.append("ISS retido (5%): ").append(BRL_FORMAT.format(iss));
 96	
 97	        return sb.toString();
 98	    }
 99	
100	    private String generateBookingReceiptText(Document doc) {
101	        StringBuilder sb = new StringBuilder();
102	        sb.append("Booking receipt no. ").append(doc.getReservationId()).append("\n");
103	        sb.append("Guest: ").append(doc.getGuestName())
104	          .append(" (passport ").append(doc.getGuestPassport())
105	          .append(", ").append(doc.getGuestCountry()).append(")\n");
106	        sb.append("Room: ").append(doc.getRoomNumber())
107	          .append(" (").append(doc.getRoomType()).append(")\n");
108	        sb.append("Check-in: ").append(doc.getCheckIn().format(EN_DATE_FORMAT))
109	          .append(" | Check-out: ").append(doc.getCheckOut().format(EN_DATE_FORMAT))
110	          .append(" | ").append(doc.getNights())
111	          .append(doc.getNights() == 1 ? " night" : " nights").append("\n");
112	        sb.append("Nights: ").append(formatBrlForEnglish(doc.getSubtotal())).append("\n");
113	
114	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
115	            sb.append("Discount: ").append(formatBrlForEnglish(doc.getDiscount())).append("\n");
116	        }
117	
118	        sb.append("Total: ").append(formatBrlForEnglish(doc.getTotal()));
119	
120	        return sb.toString();
121	    }
122	
123	    private String formatCpf(String cpf) {
124	        if (cpf == null || cpf.length() != 11) return cpf;
125	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
126	               cpf.substring(6, 9) + "-" + cpf.substring(9);
127	    }
128	
129	    private String formatCnpj(String cnpj) {
130	        if (cnpj == null || cnpj.length() != 14) return cnpj;
131	        return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
132	               cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
133	    }
134	
135	    private String formatBrlForEnglish(BigDecimal value) {
136	        String formatted = USD_FORMAT.format(value);
137	        return formatted.replace("$", "BRL ");
138	    }
139	}
