211	                .findFirst()
212	                .orElseThrow();
213	
214	            csv.append(room.getType()).append(",");
215	            csv.append(reservation.getId()).append(",");
216	            csv.append(reservation.getCheckIn().format(CSV_DATE_FORMAT)).append(",");
217	            csv.append(reservation.getCheckOut().format(CSV_DATE_FORMAT)).append("\n");
218	        }
219	
220	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
