 88	    }
 89	
 90	    @Test
 91	    void shouldCalculateDiscountForNonRefundable() {
 92	        BigDecimal subtotal = new BigDecimal("599.76");
 93	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, RatePlan.NON_REFUNDABLE);
 94	        assertEquals(new BigDecimal("89.96"), discount);
 95	    }
 96	
 97	    @Test
 98	    void shouldNotCalculateDiscountForStandard() {
 99	        BigDecimal subtotal = new BigDecimal("599.76");
